export const registerCheckCommand = (
  program: Command,
  dependencies: Required<BuildCliDependencies>,
): void => {
  program
    .command("check")
    .description("Validate required configuration before running ingest work")
    .action(async () => {
      try {
        const config = dependencies.loadConfig();
        const sourceClient = dependencies.createSourceClient(config);
        // One S3 client + one pg pool per command, built once at the
        // composition root and injected into the read-only probes
        // ([std: correctness] External adapters one-client rule).
        const s3Client = dependencies.createS3Client(config.s3);
        const pool = dependencies.createPgPool(config.staging.databaseUrl);
        const sourceConnectivity = await dependencies.checkSourceConnectivity({
          sourceClient,
          sourceUrl: new URL(config.sourceUrl),
        });
        const s3Connectivity = await dependencies.checkS3Connectivity({
          bucket: config.s3.bucket,
          sender: s3Client,
        });
        const stagingConnectivity = await runStagingCheck(dependencies, pool);
        const checks = {
          s3Connectivity,
          sourceConnectivity,
          stagingConnectivity,
        };
        const ok = connectivityOk(checks);

        writeJson({
          ok,
          checks: {
            config: { status: "passed" },
            ...checks,
          },
          config: redactConfig(config),
        });

        if (!ok) {
          process.exitCode = 2;
        }
      } catch (error) {
        if (error instanceof ConfigValidationError) {
          writeJson({
            ok: false,
            checks: {
              config: { status: "failed" },
            },
            issues: error.issues,
          });
          process.exitCode = 2;
          return;
        }

        throw error;
      }
    });
};

const runStoreRawDiscovery = async (
  dependencies: Required<BuildCliDependencies>,
  shouldStage: boolean,
): Promise<void> => {
  const configResult = loadStoreRawConfig(dependencies);
  if (!configResult.ok) {
    writeJson({
      ok: false,
      error: "discover store-raw configuration is invalid",
      issues: configResult.issues,
    });
    process.exitCode = 2;
    return;
  }

  const resources = createStoreRawResources(
    dependencies,
    configResult.config,
    shouldStage,
  );
  const discoveryReport = await discoverForStoreRaw(
    dependencies,
    configResult.config,
    resources.sourceClient,
  );
  const storageResults: StoreRawReplayResult[] = [];
  const stagingResults: IngestStagingResult[] = [];

  if (discoveryReport.ok) {
    for (const candidate of discoveryReport.candidates) {
      // Raw replay storage is intentionally sequential for clear source/storage evidence.
      const result = await dependencies.storeRawReplay({
        byteClient: resources.byteClient,
        candidate,
        storage: resources.storage,
      });
      storageResults.push(result);

      if (shouldStage) {
        // Staging follows the raw evidence for the same candidate in order.
        const stagingResult = await stageRawEvidence(
          dependencies,
          resources.stagingRepository,
          result,
        );
        stagingResults.push(stagingResult);
      }
    }
  }

  const rawCounts = countRawStorage(discoveryReport, storageResults);
  const stagingCounts = countStaging(stagingResults);
  const ok =
    discoveryReport.ok &&
    rawCounts.conflict === 0 &&
    rawCounts.failed === 0 &&
    stagingCounts.conflict === 0 &&
    stagingCounts.failed === 0;

  const report = {
    ok,
    mode: storeRawMode(shouldStage),
    sourceUrl: discoveryReport.sourceUrl,
    generatedAt: discoveryReport.generatedAt,
    counts: storeRawCounts(shouldStage, rawCounts, stagingCounts),
    candidates: discoveryReport.candidates,
    diagnostics: discoveryReport.diagnostics,
    storage: storageResults,
  };

  if (shouldStage) {
    writeJson({ ...report, staging: stagingResults });
  } else {
    writeJson(report);
  }

  if (!ok) {
    process.exitCode = 2;
  }
};

export const registerDiscoverCommand = (
  program: Command,
  dependencies: Required<BuildCliDependencies>,
): void => {
  program
    .command("discover")
    .description("Discover replay candidates")
    .option(
      "--dry-run",
      "report candidates without writing S3 or staging records",
    )
    .option(
      "--store-raw",
      "discover candidates and store raw replay objects without staging",
    )
    .option("--stage", "write pending server-2 staging rows after raw storage")
    .action(async (options: DiscoverOptions) => {
      if (options.dryRun === true && options.storeRaw === true) {
        writeJson({
          ok: false,
          error: "discover accepts only one mode: --dry-run or --store-raw",
        });
        process.exitCode = 2;
        return;
      }

      if (options.stage === true && options.storeRaw !== true) {
        writeJson({
          ok: false,
          error: "discover --stage requires --store-raw",
        });
        process.exitCode = 2;
        return;
      }

      if (options.storeRaw === true) {
        await runStoreRawDiscovery(dependencies, options.stage === true);
        return;
      }

      if (options.dryRun !== true) {
        writeJson({
          ok: false,
          error: "discover requires --dry-run or --store-raw",
        });
        process.exitCode = 2;
        return;
      }

      await runDryRunDiscovery(dependencies);
    });
};

export const registerRunOnceCommand = (
  program: Command,
  dependencies: Required<BuildCliDependencies>,
): void => {
  program
    .command("run-once")
    .description("Execute one scheduled ingest cycle")
    .option(
      "--resume",
      "resume from the last completed page using the source checkpoint",
    )
    .option(
      "--emit-evidence",
      "write a durable per-candidate evidence artifact to S3",
    )
    .option(
      "--evidence-file <path>",
      "also write the evidence artifact to a local file (dev only)",
    )
    .action(async (options: RunOnceOptions) => {
      const startedAt = dependencies.now();
      const runId = dependencies.createRunId(startedAt);
      const rootLogger = dependencies.createLogger();
      const log = rootLogger.child({ runId });
      // CORE-02 substrate: the per-run child logger is keyed by runId. stdout
      // cleanliness for the JSON summary contract (parsed by cli.test.ts) is
      // guaranteed by the logger writing to stderr (createLogger defaults its
      // destination to process.stderr), not by the log level — so emitting at
      // debug or any level cannot interleave with the stdout summary.
      const configResult = loadStoreRawConfig(dependencies);

      if (!configResult.ok) {
        const finishedAt = dependencies.now().toISOString();
        const summary = buildConfigInvalidRunSummary({
          finishedAt,
          issues: configResult.issues,
          runId,
          startedAt: startedAt.toISOString(),
        });
        writeJson(summary);
        process.exitCode = runExitCode(summary);
        return;
      }

      const resources = createStoreRawResources(
        dependencies,
        configResult.config,
        true,
      );
      const result = await dependencies.runOnce({
        attempts: configResult.config.sourceRetryAttempts,
        byteClient: resources.byteClient,
        checkpointStore: resources.checkpointStore,
        concurrency: configResult.config.sourceConcurrency,
        discoverReplays: dependencies.discoverReplaysDryRun,
        emitEvidence: options.emitEvidence === true,
        evidenceStore: resources.evidenceStore,
        log,
        now: dependencies.now,
        onRetry: buildRetryWarnEmitter(log),
        requestSpacingMs: configResult.config.sourceRequestSpacingMs,
        resume: options.resume === true,
        runId,
        ...maxPagesOption(configResult.config.sourceMaxPages),
        ...evidenceFileOption(options.evidenceFile),
        sourceClient: resources.sourceClient,
        sourceUrl: new URL(configResult.config.sourceUrl),
        stageRawReplay: dependencies.stageRawReplay,
        stagingRepository: requireStagingRepository(
          resources.stagingRepository,
        ),
        storage: resources.storage,
        storeRawReplay: dependencies.storeRawReplay,
        writeEvidenceFile: dependencies.writeEvidenceFile,
      });

      // D-02 (PROG-02): stdout carries exactly one compact JSON document.
      // The full RunSummary (with heavy arrays) is kept in-memory for the
      // opt-in evidence artifact; the stdout projection strips all arrays.
      writeJson(toCompactSummary(result.summary));
      // D-16 (PROG-04): await the pino flush AFTER the stdout write and BEFORE
      // setting process.exitCode so the final NDJSON lines drain cleanly without
      // calling process.exit() (streams drain naturally on exit).
      await flushLogger(rootLogger);
      process.exitCode = result.exitCode;
    });
};

export const registerWatchCommand = (
  program: Command,
  dependencies: Required<BuildCliDependencies>,
): void => {
  program
    .command("watch")
    .description(
      "Run an always-on page-1 poll loop, ingesting new replays within seconds",
    )
    .action(async () => {
      const startedAt = dependencies.now();
      const runId = dependencies.createRunId(startedAt);
      const rootLogger = dependencies.createLogger();
      const log = rootLogger.child({ runId });
      const configResult = loadStoreRawConfig(dependencies);

      if (!configResult.ok) {
        // §C/§D: config validates before any side effect, so nothing is
        // touched. Emit the config-invalid summary and exit 2 (mirrors
        // run-once exactly — the only exit-2 path).
        const finishedAt = dependencies.now().toISOString();
        const summary = buildConfigInvalidRunSummary({
          finishedAt,
          issues: configResult.issues,
          runId,
          startedAt: startedAt.toISOString(),
        });
        writeJson(summary);
        process.exitCode = runExitCode(summary);
        return;
      }

      const resources = createStoreRawResources(
        dependencies,
        configResult.config,
        true,
      );
      const { dispose, shouldStop } = createShutdownSeam();

      try {
        // WATCH-02: the watcher is checkpoint-independent —
        // resources.checkpointStore is deliberately NOT passed into the loop
        // (runWatchLoop has no checkpointStore seam), so the watcher can neither
        // read nor advance the source checkpoint.
        const result = await dependencies.runWatchLoop({
          attempts: configResult.config.sourceRetryAttempts,
          byteClient: resources.byteClient,
          concurrency: configResult.config.sourceConcurrency,
          createRunId: dependencies.createRunId,
          discoverReplays: dependencies.discoverReplaysDryRun,
          heartbeatPath: configResult.config.watchHeartbeatPath,
          intervalMs: configResult.config.watchIntervalMs,
          log,
          now: dependencies.now,
          requestSpacingMs: configResult.config.sourceRequestSpacingMs,
          shouldStop,
          sourceClient: resources.sourceClient,
          sourceUrl: new URL(configResult.config.sourceUrl),
          stageRawReplay: dependencies.stageRawReplay,
          stagingRepository: requireStagingRepository(
            resources.stagingRepository,
          ),
          storage: resources.storage,
          storeRawReplay: dependencies.storeRawReplay,
          writeHeartbeat: dependencies.writeHeartbeat,
        });

        // D-16 (PROG-04): drain pino BEFORE setting process.exitCode, never
        // process.exit() mid-stream. exitCode 0 on clean shutdown.
        await flushLogger(rootLogger);
        process.exitCode = result.exitCode;
      } finally {
        // Production-owned listener cleanup: remove both signal handlers
        // (including the unfired counterpart) so the daemon never leaks a
        // process listener and does not lean on a test harness's
        // removeAllListeners.
        dispose();
      }
    });
};

const toReplayCandidate = (
  candidate: SourceCandidateFixture,
  index: number,
  pageUrl: URL,
): CandidateFixtureResult => {
  if (
    typeof candidate.filename !== "string" ||
    candidate.filename.trim().length === 0 ||
    typeof candidate.url !== "string" ||
    candidate.url.trim().length === 0 ||
    !isValidFixtureUrl(candidate.url)
  ) {
    return {
      diagnostic: {
        candidateIndex: index,
        code: "malformed_row",
        message: "Source fixture candidate did not include filename and URL",
        severity: "warning",
        sourceUrl: pageUrl.toString(),
      },
    };
  }

  const source: MutableReplaySource = {
    url: candidate.url,
  };

  if (candidate.externalId !== undefined) {
    source.externalId = candidate.externalId;
  }

  if (typeof candidate.page === "number") {
    source.page = candidate.page;
  }

  if (candidate.rawUrl !== undefined) {
    source.rawUrl = candidate.rawUrl;
  }

  const metadata: MutableReplayMetadata = {};

  if (candidate.discoveredAt !== undefined) {
    metadata.discoveredAt = candidate.discoveredAt;
  }

  if (candidate.missionText !== undefined) {
    metadata.missionText = candidate.missionText;
  }

  if (typeof candidate.serverId === "number") {
    metadata.serverId = candidate.serverId;
  }

  if (candidate.world !== undefined) {
    metadata.world = candidate.world;
  }

  const replayCandidate: ReplayCandidate = {
    identity: {
      filename: candidate.filename,
    },
    source,
  };

  if (Object.keys(metadata).length > 0) {
    return {
      candidate: {
        ...replayCandidate,
        metadata,
      },
    };
  }

  return {
    candidate: replayCandidate,
  };
};

const collectCandidateDiagnostics = (
  candidates: readonly ReplayCandidate[],
): DiscoverPageCandidatesResult => {
  const candidatesByFilename = new Map<string, CandidateRegistryEntry[]>();
  const emittedExactCandidates = new Set<string>();
  const outputCandidates: ReplayCandidate[] = [];
  const diagnostics: DiscoveryDiagnostic[] = [];

  for (const candidate of candidates) {
    const serialized = JSON.stringify(candidate);
    const existingEntries =
      candidatesByFilename.get(candidate.identity.filename) ?? [];
    const exactCandidateExists = emittedExactCandidates.has(serialized);

    if (existingEntries.length > 0) {
      diagnostics.push(
        withOptionalDiagnosticEvidence(
          {
            candidateIndex: outputCandidates.length,
            code: "duplicate_filename",
            message: "Filename appeared more than once in source discovery",
            severity: "warning",
            sourceUrl: candidate.source.url,
          },
          diagnosticEvidence(
            candidate.source.externalId,
            candidate.source.page,
          ),
        ),
      );

      if (hasChangedMetadata(existingEntries, candidate)) {
        diagnostics.push(
          withOptionalDiagnosticEvidence(
            {
              candidateIndex: outputCandidates.length,
              code: "changed_metadata",
              message:
                "Filename/source ID metadata changed within one discovery run",
              severity: "warning",
              sourceUrl: candidate.source.url,
            },
            diagnosticEvidence(
              candidate.source.externalId,
              candidate.source.page,
            ),
          ),
        );
      }
    }

    if (!exactCandidateExists) {
      outputCandidates.push(candidate);
      emittedExactCandidates.add(serialized);
    }

    existingEntries.push({ candidate, serialized });
    candidatesByFilename.set(candidate.identity.filename, existingEntries);
  }

  return { candidates: outputCandidates, diagnostics };
};

const discoverPageCandidates = async (input: {
  readonly detailReadOptions: ReadOptions;
  readonly fixture: SourceFixture | undefined;
  readonly page: number;
  readonly pageUrl: URL;
  readonly sourceClient: SourceClient;
  readonly sourceText: string;
}): Promise<DiscoverPageCandidatesResult> => {
  if (input.fixture !== undefined) {
    return collectFixtureCandidates(input.fixture, input.pageUrl);
  }

  const candidates: ReplayCandidate[] = [];
  const diagnostics: DiscoveryDiagnostic[] = [];
  const rows = extractReplayRows(input.sourceText, input.page, input.pageUrl);

  for (const row of rows) {
    if (row.source.url === undefined) {
      diagnostics.push({
        code: "malformed_row",
        message: "Source row did not include a replay link",
        page: row.page,
        severity: "warning",
        sourceUrl: input.pageUrl.toString(),
      });
    } else {
      // Source requests are intentionally sequential to avoid aggressive polling.
      const candidate = await discoverRowCandidate({
        detailReadOptions: input.detailReadOptions,
        row,
        sourceClient: input.sourceClient,
        sourceUrl: row.source.url,
      });

      if (candidate === undefined) {
        diagnostics.push(
          withOptionalDiagnosticEvidence(
            {
              code: "missing_filename",
              message: "Replay detail page did not include a filename",
              severity: "warning",
              sourceUrl: row.source.url,
            },
            diagnosticEvidence(row.source.externalId, row.page),
          ),
        );
      } else {
        candidates.push(candidate);
      }
    }
  }

  const candidateDiagnostics = collectCandidateDiagnostics(candidates);

  return {
    candidates: candidateDiagnostics.candidates,
    diagnostics: [...diagnostics, ...candidateDiagnostics.diagnostics],
  };
};

const parseReplayRow = (
  rowHtml: string,
  page: number,
  sourceUrl: URL,
): ReplayRowObservation => {
  const cells = [
    ...rowHtml.matchAll(/<td[^>]*>(?<cell>[\s\S]*?)<\/td>/giu),
  ].map((match) => getMatchGroup(match, "cell"));
  const link =
    /<a\b[^>]*\bhref=(?<quote>["'])(?<href>.*?)\k<quote>[^>]*>(?<text>[\s\S]*?)<\/a>/iu.exec(
      cells[0] ?? "",
    );
  const href = link?.groups?.["href"]?.trim();
  const url = hrefToUrl(href, sourceUrl);
  const externalId = /\/replays\/(?<id>[^/?#]+)/iu.exec(url ?? "")?.groups?.[
    "id"
  ];
  const serverIdText = stripTags(cells[2] ?? "").trim();
  const serverId = Number.parseInt(serverIdText, 10);
  const source: MutableReplayRowSource = {};
  const metadata: MutableReplayRowMetadata = {};

  if (externalId !== undefined) {
    source.externalId = externalId;
  }

  if (url !== undefined) {
    source.url = url;
  }

  const missionText = stripTags(link?.groups?.["text"] ?? "").trim();
  const world = stripTags(cells[1] ?? "").trim();

  if (missionText.length > 0) {
    metadata.missionText = missionText;
  }

  if (world.length > 0) {
    metadata.world = world;
  }

  if (!Number.isNaN(serverId)) {
    metadata.serverId = serverId;
  }

  return {
    metadata,
    page,
    source,
  };
};

const runWithRetry = async <TResult>(
  wiring: RetryWiring<TResult>,
  options?: SourceFetchOptions,
): Promise<TResult> => {
  const attempts = options?.attempts ?? noRetryAttempts;
  const callerSignal = options?.signal ?? new AbortController().signal;

  let retryOptions: RetrySourceReadOptions<TResult> = {
    attempts,
    classify: wiring.classify,
    phase: wiring.phase,
    read: wiring.read,
    signal: callerSignal,
    url: wiring.url.toString(),
  };

  if (options?.page !== undefined) {
    retryOptions = { ...retryOptions, page: options.page };
  }

  if (options?.onRetry !== undefined) {
    retryOptions = { ...retryOptions, onRetry: options.onRetry };
  }

  if (wiring.retryAfterMs !== undefined) {
    retryOptions = { ...retryOptions, retryAfterMs: wiring.retryAfterMs };
  }

  if (options?.sleep !== undefined) {
    retryOptions = { ...retryOptions, sleep: options.sleep };
  }

  if (options?.random !== undefined) {
    retryOptions = { ...retryOptions, random: options.random };
  }

  if (options?.now !== undefined) {
    retryOptions = { ...retryOptions, now: options.now };
  }

  return withRetry(retryOptions);
};

